def assemble(sku, ctx):
    level = brownout.level()
    futures = {}
    for dep in registry.deps_for('pdp'):
        if not policy.shouldCall(dep, level):
            mark_degraded(dep, 'brownout'); continue
        futures[dep] = client.call_async(dep, sku, timeout=policy.budgetFor(dep))
    out = {}
    for dep, f in futures.items():
        try:
            out[dep] = f.result(timeout=remaining(ctx, dep))
        except (Timeout, CircuitOpen, Error):
            if dep.tier == 'T0' and dep.degraded_mode == 'block':
                return error_page_or_snapshot(sku)
            out[dep] = policy.fallbackFor(dep).get(sku, ctx)
            mark_degraded(dep, 'fallback')
    return render(out, degraded_list())

def get(key, loader):
    e = cache.get(key)
    if e and e.age < SOFT_TTL: return e.value, e.age
    if e and e.age < HARD_TTL:
        if lock.try_acquire(key):          # single-flight
            spawn(refresh, key, loader)
        return e.value, e.age              # stale-while-revalidate
    try:
        v = single_flight(key, loader)
        cache.put(key, v); return v, 0
    except Error:
        if e: return e.value, e.age        # stale-if-error past soft TTL
        raise
